import { test, expect } from '@playwright/test';

test("User Login with Valid Credentials", async ({ page }) => {
  // Step 1: navigate
  await page.goto("https://opencart.abstracta.us/index.php?route=account/login");
  // Step 2: fill username
  await page.getByRole("textbox", { name: "E-Mail Address" }).fill(process.env.APP_USERNAME || '');
  // Step 3: fill password
  await page.getByRole("textbox", { name: "Password" }).fill(process.env.APP_PASSWORD || '');
  // Step 4: click login
  await page.getByRole("button", { name: "Login" }).click();
  // Step 5: assert URL
  await expect.poll(() => page.url()).toContain("route=account/account");
  // Step 5: assert text
  await expect(page.locator('body')).toContainText("Edit Account");
});
